css:
.fx-bsh{display:grid;gap:1.4em;justify-items:center;text-align:center}
.fx-bsh h2{font-size:2.3em}.fx-bsh p{opacity:.6}.fx-bsh .row{display:flex;gap:1em;flex-wrap:wrap;justify-content:center}
.fx-bsh .b{position:relative;overflow:hidden;padding:1em 1.9em;border-radius:var(--radius);border:0;font:700 .95em var(--font-body);color:var(--on-primary);cursor:pointer;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 55%,var(--accent)));box-shadow:0 12px 26px -12px var(--primary);transition:transform calc(.25s/var(--speed))}
.fx-bsh .b.acc{color:var(--on-accent);background:linear-gradient(135deg,var(--accent),color-mix(in srgb,var(--accent) 55%,var(--primary)));box-shadow:0 12px 26px -12px var(--accent)}
.fx-bsh .b.out{background:transparent;color:var(--primary);box-shadow:inset 0 0 0 1.5px var(--primary)}
.fx-bsh .b::after{content:"";position:absolute;top:0;left:-70%;width:40%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.6),transparent);transform:skewX(-20deg)}
.fx-bsh .b:hover{transform:translateY(-2px)}.fx-bsh .b:hover::after{left:140%;transition:left calc(.85s/var(--speed)) ease}
@media(prefers-reduced-motion:reduce){.fx-bsh .b::after{display:none}}
/* touch: :hover mirrored as .is-tap */
.fx-bsh .b.is-tap{transform:translateY(-2px)}
.fx-bsh .b.is-tap::after{left:140%;transition:left calc(.85s/var(--speed)) ease}
